1	// Package summarize provides AI-powered summarization of development sessions.
2	package summarize
3	
4	import (
5		"bytes"
6		"context"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"strings"
11	
12		"github.com/entireio/cli/cmd/entire/cli/agent"
13		"github.com/entireio/cli/cmd/entire/cli/agent/factoryaidroid"
14		"github.com/entireio/cli/cmd/entire/cli/agent/geminicli"
15		"github.com/entireio/cli/cmd/entire/cli/agent/opencode"
16		"github.com/entireio/cli/cmd/entire/cli/agent/types"
17		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
18		"github.com/entireio/cli/cmd/entire/cli/transcript"
19		"github.com/entireio/cli/cmd/entire/cli/transcript/compact"
20		"github.com/entireio/cli/redact"
21	)
22	
23	// GenerateFromTranscript generates a summary from pre-redacted transcript bytes.
24	// This is the shared implementation used by both explain --generate and auto-summarize.
25	//
26	// Parameters:
27	//   - ctx: context for cancellation
28	//   - transcriptBytes: pre-redacted transcript (JSONL or JSON format depending on agent)
29	//   - filesTouched: list of files modified during the session
30	//   - agentType: the agent type to determine transcript format
31	//   - generator: summary generator to use (if nil, uses default ClaudeGenerator)
32	//
33	// Returns nil, error if transcript is empty or cannot be parsed.
34	func GenerateFromTranscript(ctx context.Context, transcriptBytes redact.RedactedBytes, filesTouched []string, agentType types.AgentType, generator Generator) (*checkpoint.Summary, error) {
35		if transcriptBytes.Len() == 0 {
36			return nil, errors.New("empty transcript")
37		}
38	
39		// Build condensed transcript for summarization
40		condensed, err := BuildCondensedTranscriptFromBytes(transcriptBytes, agentType)
41		if err != nil {
42			return nil, fmt.Errorf("failed to parse transcript: %w", err)
43		}
44		if len(condensed) == 0 {
45			return nil, errors.New("transcript has no content to summarize")
46		}
47	
48		input := Input{
49			Transcript:   condensed,
50			FilesTouched: filesTouched,
51		}
52	
53		if generator == nil {
54			generator = &ClaudeGenerator{}
55		}
56	
57		summary, err := generator.Generate(ctx, input)
58		if err != nil {
59			return nil, err //nolint:wrapcheck // preserve *ClaudeError for errors.As at the explain layer
60		}
61	
62		return summary, nil
63	}
64	
65	// Generator generates checkpoint summaries using an LLM.
66	type Generator interface {
67		// Generate creates a summary from checkpoint data.
68		// Returns the generated summary or an error if generation fails.
69		Generate(ctx context.Context, input Input) (*checkpoint.Summary, error)
70	}
71	
72	// ResolveModel returns the effective model to use for summary generation.
73	// When the provider is Claude Code and no model is configured, it falls back
74	// to DefaultModel ("sonnet") — the summarize package's quality/cost choice,
75	// which differs from Claude Code's own invocation default ("haiku"). For
76	// other providers, an empty model means "use the provider CLI's own default",
77	// so we leave it unchanged.
78	func ResolveModel(name types.AgentName, model string) string {
79		if name == agent.AgentNameClaudeCode && model == "" {
80			return DefaultModel
81		}
82		return model
83	}
84	
85	// Input contains condensed checkpoint data for summarization.
86	type Input struct {
87		// Transcript is the condensed transcript entries
88		Transcript []Entry
89	
90		// FilesTouched are the files modified during the session
91		FilesTouched []string
92	}
93	
94	// EntryType represents the type of a transcript entry.
95	type EntryType string
96	
97	const (
98		// EntryTypeUser indicates a user prompt entry.
99		EntryTypeUser EntryType = "user"
100		// EntryTypeAssistant indicates an assistant response entry.
101		EntryTypeAssistant EntryType = "assistant"
102		// EntryTypeTool indicates a tool call entry.
103		EntryTypeTool EntryType = "tool"
104	)
105	
106	// Entry represents one item in the condensed transcript.
107	type Entry struct {
108		// Type is the entry type (user, assistant, tool)
109		Type EntryType
110	
111		// Content is the text content for user/assistant entries
112		Content string
113	
114		// ToolName is the name of the tool (for tool entries)
115		ToolName string
116	
117		// ToolDetail is a description or file path (for tool entries)
118		ToolDetail string
119	}
120	
121	// minimalDetailTools lists tools that should show only essential details in summaries.
122	// These tools often have verbose outputs that don't add value to summarization.
123	// The detail shown is typically just a path, URL, or identifier rather than full content.
124	var minimalDetailTools = map[string]bool{
125		"Skill":    true, // Show skill name only, not loaded content
126		"Read":     true, // Show file path only, not file contents
127		"WebFetch": true, // Show URL only, not fetched content
128	}
129	
130	// BuildCondensedTranscriptFromBytes parses pre-redacted transcript bytes and extracts a condensed view.
131	// This is a convenience function that combines parsing and condensing.
132	// The agentType parameter determines which parser to use (Claude/OpenCode JSONL vs Gemini JSON).
133	func BuildCondensedTranscriptFromBytes(content redact.RedactedBytes, agentType types.AgentType) ([]Entry, error) {
134		switch agentType {
135		case agent.AgentTypeGemini:
136			return buildCondensedTranscriptFromGemini(content)
137		case agent.AgentTypeFactoryAIDroid:
138			return buildCondensedTranscriptFromDroid(content)
139		case agent.AgentTypeOpenCode:
140			return buildCondensedTranscriptFromOpenCode(content)
141		case agent.AgentTypeCodex:
142			return buildCondensedTranscriptFromCodex(content)
143		case agent.AgentTypeClaudeCode, agent.AgentTypeCursor, agent.AgentTypeUnknown:
144			// Claude/cursor format - fall through to shared logic below
145		}
146		// Claude format (JSONL) - handles Claude Code, Unknown, and any future agent types
147		lines, err := transcript.ParseFromBytes(content.Bytes())
148		if err != nil {
149			return nil, fmt.Errorf("failed to parse transcript: %w", err)
150		}
151		return BuildCondensedTranscript(lines), nil
152	}
153	
154	// buildCondensedTranscriptFromGemini parses Gemini JSON transcript and extracts a condensed view.
155	func buildCondensedTranscriptFromGemini(redacted redact.RedactedBytes) ([]Entry, error) {
156		geminiTranscript, err := geminicli.ParseTranscript(redacted.Bytes())
157		if err != nil {
158			return nil, fmt.Errorf("failed to parse Gemini transcript: %w", err)
159		}
160	
161		var entries []Entry
162		for _, msg := range geminiTranscript.Messages {
163			switch msg.Type {
164			case geminicli.MessageTypeUser:
165				if msg.Content != "" {
166					entries = append(entries, Entry{
167						Type:    EntryTypeUser,
168						Content: msg.Content,
169					})
170				}
171			case geminicli.MessageTypeGemini:
172				// Add assistant content
173				if msg.Content != "" {
174					entries = append(entries, Entry{
175						Type:    EntryTypeAssistant,
176						Content: msg.Content,
177					})
178				}
179				// Add tool calls
180				for _, tc := range msg.ToolCalls {
181					entries = append(entries, Entry{
182						Type:       EntryTypeTool,
183						ToolName:   tc.Name,
184						ToolDetail: extractGenericToolDetail(tc.Args),
185					})
186				}
187			}
188		}
189	
190		return entries, nil
191	}
192	
193	// buildCondensedTranscriptFromOpenCode parses OpenCode export JSON transcript and extracts a condensed view.
194	func buildCondensedTranscriptFromOpenCode(redacted redact.RedactedBytes) ([]Entry, error) {
195		session, err := opencode.ParseExportSession(redacted.Bytes())
196		if err != nil {
197			return nil, fmt.Errorf("failed to parse OpenCode transcript: %w", err)
198		}
199		if session == nil {
200			return nil, nil
201		}
202	
203		var entries []Entry
204		for _, msg := range session.Messages {
205			switch msg.Info.Role {
206			case "user":
207				text := opencode.ExtractTextFromParts(msg.Parts)
208				if text != "" {
209					entries = append(entries, Entry{
210						Type:    EntryTypeUser,
211						Content: text,
212					})
213				}
214			case "assistant":
215				text := opencode.ExtractTextFromParts(msg.Parts)
216				if text != "" {
217					entries = append(entries, Entry{
218						Type:    EntryTypeAssistant,
219						Content: text,
220					})
221				}
222				for _, part := range msg.Parts {
223					if part.Type == "tool" && part.State != nil {
224						entries = append(entries, Entry{
225							Type:       EntryTypeTool,
226							ToolName:   part.Tool,
227							ToolDetail: extractOpenCodeToolDetail(part.State.Input),
228						})
229					}
230				}
231			}
232		}
233	
234		return entries, nil
235	}
236	
237	// buildCondensedTranscriptFromCodex converts Codex rollout JSONL into the compact
238	// transcript format, then reuses the shared transcript condensation logic.
239	func buildCondensedTranscriptFromCodex(content redact.RedactedBytes) ([]Entry, error) {
240		compacted, err := compact.Compact(content, compact.MetadataFields{
241			Agent:      "codex",
242			CLIVersion: "summarize",
243		})
244		if err != nil {
245			return nil, fmt.Errorf("failed to compact Codex transcript: %w", err)
246		}
247	
248		type compactUserTextBlock struct {
249			Text string `json:"text"`
250		}
251		type compactAssistantBlock struct {
252			Type  string          `json:"type"`
253			Text  string          `json:"text,omitempty"`
254			Name  string          `json:"name,omitempty"`
255			Input json.RawMessage `json:"input,omitempty"`
256		}
257		type compactLine struct {
258			Type    string          `json:"type"`
259			Content json.RawMessage `json:"content"`
260		}
261	
262		var entries []Entry
263		for _, lineBytes := range splitCompactJSONL(compacted) {
264			var line compactLine
265			if err := json.Unmarshal(lineBytes, &line); err != nil {
266				continue
267			}
268	
269			switch line.Type {
270			case transcript.TypeUser:
271				var blocks []compactUserTextBlock
272				if err := json.Unmarshal(line.Content, &blocks); err != nil {
273					continue
274				}
275				for _, block := range blocks {
276					if block.Text != "" {
277						entries = append(entries, Entry{
278							Type:    EntryTypeUser,
279							Content: block.Text,
280						})
281					}
282				}
283			case transcript.TypeAssistant:
284				var blocks []compactAssistantBlock
285				if err := json.Unmarshal(line.Content, &blocks); err != nil {
286					continue
287				}
288				for _, block := range blocks {
289					switch block.Type {
290					case transcript.ContentTypeText:
291						if block.Text != "" {
292							entries = append(entries, Entry{
293								Type:    EntryTypeAssistant,
294								Content: block.Text,
295							})
296						}
297					case transcript.ContentTypeToolUse:
298						var input map[string]interface{}
299						if err := json.Unmarshal(block.Input, &input); err != nil {
300							input = nil
301						}
302						entries = append(entries, Entry{
303							Type:       EntryTypeTool,
304							ToolName:   block.Name,
305							ToolDetail: extractGenericToolDetail(input),
306						})
307					}
308				}
309			}
310		}
311	
312		return entries, nil
313	}
314	
315	// buildCondensedTranscriptFromDroid parses Droid transcript and extracts a condensed view.
316	func buildCondensedTranscriptFromDroid(redacted redact.RedactedBytes) ([]Entry, error) {
317		droidLines, _, err := factoryaidroid.ParseDroidTranscriptFromBytes(redacted.Bytes(), 0)
318		if err != nil {
319			return nil, fmt.Errorf("failed to parse Droid transcript: %w", err)
320		}
321		return BuildCondensedTranscript(droidLines), nil
322	}
323	
324	// extractOpenCodeToolDetail extracts a detail string from an OpenCode tool's input map.
325	// OpenCode uses camelCase keys (e.g., "filePath" instead of "file_path").
326	func extractOpenCodeToolDetail(input map[string]interface{}) string {
327		for _, key := range []string{"description", "command", "filePath", "path", "pattern"} {
328			if v, ok := input[key].(string); ok && v != "" {
329				return v
330			}
331		}
332		return ""
333	}
334	
335	// extractGenericToolDetail extracts an appropriate detail string from a tool's input/args map.
336	// Checks common fields in order of preference.
337	func extractGenericToolDetail(input map[string]interface{}) string {
338		if input == nil {
339			return ""
340		}
341		for _, key := range []string{"description", "command", "cmd", "file_path", "path", "pattern"} {
342			if v, ok := input[key].(string); ok && v != "" {
343				return v
344			}
345		}
346		return ""
347	}
348	
349	func splitCompactJSONL(data []byte) [][]byte {
350		var lines [][]byte
351		for _, line := range bytes.Split(data, []byte("\n")) {
352			line = bytes.TrimSpace(line)
353			if len(line) > 0 {
354				lines = append(lines, line)
355			}
356		}
357		return lines
358	}
359	
360	// BuildCondensedTranscript extracts a condensed view of the transcript.
361	// It processes user prompts, assistant responses, and tool calls into
362	// a simplified format suitable for LLM summarization.
363	func BuildCondensedTranscript(lines []transcript.Line) []Entry {
364		var entries []Entry
365	
366		for _, line := range lines {
367			switch line.Type {
368			case transcript.TypeUser:
369				if entry := extractUserEntry(line); entry != nil {
370					entries = append(entries, *entry)
371				}
372			case transcript.TypeAssistant:
373				assistantEntries := extractAssistantEntries(line)
374				entries = append(entries, assistantEntries...)
375			}
376		}
377	
378		return entries
379	}
380	
381	// skillContentPrefix identifies user messages that are skill content injections.
382	// These are injected after a Skill tool call and contain the full skill instructions.
383	const skillContentPrefix = "Base directory for this skill:"
384	
385	// extractUserEntry extracts a user entry from a transcript line.
386	// Returns nil if the line doesn't contain a valid user prompt or is skill content.
387	func extractUserEntry(line transcript.Line) *Entry {
388		content := transcript.ExtractUserContent(line.Message)
389		if content == "" {
390			return nil
391		}
392	
393		// Skip skill content injections - these are verbose skill instructions
394		// injected as user messages after Skill tool invocations in Claude Code.
395		// The prefix "Base directory for this skill:" is added by the superpowers
396		// plugin when loading skill content. This filtering reduces transcript noise
397		// since skill content is documentation, not user intent.
398		if strings.HasPrefix(content, skillContentPrefix) {
399			return nil
400		}
401	
402		return &Entry{
403			Type:    EntryTypeUser,
404			Content: content,
405		}
406	}
407	
408	// extractAssistantEntries extracts assistant and tool entries from a transcript line.
409	func extractAssistantEntries(line transcript.Line) []Entry {
410		var msg transcript.AssistantMessage
411		if err := json.Unmarshal(line.Message, &msg); err != nil {
412			return nil
413		}
414	
415		var entries []Entry
416	
417		for _, block := range msg.Content {
418			switch block.Type {
419			case transcript.ContentTypeText:
420				if block.Text != "" {
421					entries = append(entries, Entry{
422						Type:    EntryTypeAssistant,
423						Content: block.Text,
424					})
425				}
426			case transcript.ContentTypeToolUse:
427				var input transcript.ToolInput
428				_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing
429	
430				detail := extractToolDetail(block.Name, input)
431	
432				entries = append(entries, Entry{
433					Type:       EntryTypeTool,
434					ToolName:   block.Name,
435					ToolDetail: detail,
436				})
437			}
438		}
439	
440		return entries
441	}
442	
443	// extractToolDetail extracts an appropriate detail string for a tool call.
444	// For tools in minimalDetailTools, only essential identifiers are shown.
445	// For other tools, the full detail chain is used.
446	func extractToolDetail(toolName string, input transcript.ToolInput) string {
447		// For minimal detail tools, extract only the essential identifier
448		if minimalDetailTools[toolName] {
449			switch toolName {
450			case "Skill":
451				return input.Skill
452			case "Read":
453				if input.FilePath != "" {
454					return input.FilePath
455				}
456				return input.NotebookPath
457			case "WebFetch":
458				return input.URL
459			}
460		}
461	
462		// For other tools, use the full detail chain
463		if input.Description != "" {
464			return input.Description
465		}
466		if input.Command != "" {
467			return input.Command
468		}
469		if input.FilePath != "" {
470			return input.FilePath
471		}
472		if input.NotebookPath != "" {
473			return input.NotebookPath
474		}
475		return input.Pattern
476	}
477	
478	// FormatCondensedTranscript formats an Input into a human-readable string for LLM.
479	// The format is:
480	//
481	//	[User] user prompt here
482	//
483	//	[Assistant] assistant response here
484	//
485	//	[Tool] ToolName: description or file path
486	func FormatCondensedTranscript(input Input) string {
487		var sb strings.Builder
488	
489		for i, entry := range input.Transcript {
490			if i > 0 {
491				sb.WriteString("\n")
492			}
493	
494			switch entry.Type {
495			case EntryTypeUser:
496				sb.WriteString("[User] ")
497				sb.WriteString(entry.Content)
498				sb.WriteString("\n")
499			case EntryTypeAssistant:
500				sb.WriteString("[Assistant] ")
501				sb.WriteString(entry.Content)
502				sb.WriteString("\n")
503			case EntryTypeTool:
504				sb.WriteString("[Tool] ")
505				sb.WriteString(entry.ToolName)
506				if entry.ToolDetail != "" {
507					sb.WriteString(": ")
508					sb.WriteString(entry.ToolDetail)
509				}
510				sb.WriteString("\n")
511			}
512		}
513	
514		if len(input.FilesTouched) > 0 {
515			sb.WriteString("\n[Files Modified]\n")
516			for _, file := range input.FilesTouched {
517				fmt.Fprintf(&sb, "- %s\n", file)
518			}
519		}
520	
521		return sb.String()
522	}
523

