	result, err := agent.RunIsolatedTextGeneratorCLI(ctx, g.CommandRunner, "gemini", "gemini", args, prompt)
	if err != nil {
		return "", fmt.Errorf("gemini text generation failed: %w", err)
	}
	return result, nil
}

