```go
// RunStreamingCLI executes a provider CLI in streaming mode, dispatches
// each NDJSON line to handler, and returns the final result text (or a
// classified error on envelope/exit failure).
//
// See the design doc's "Layer 2" section for the full branch table;
// this implementation adds features incrementally via follow-up tasks.
func RunStreamingCLI(
    ctx context.Context,
    cfg StreamConfig,
    handler StreamLineHandler,
    progress ProgressFn,
) (string, error) {
    runner := cfg.Runner
    if runner == nil {
        runner = exec.CommandContext
    }

    cmd := runner(ctx, cfg.Binary, cfg.Args...)
    cmd.Dir = os.TempDir()
    cmd.Env = StripGitEnv(os.Environ())
    if cfg.Stdin != "" {
        cmd.Stdin = strings.NewReader(cfg.Stdin)
    }

    stdout, err := cmd.StdoutPipe()
    if err != nil {
        return "", fmt.Errorf("%s: stdout pipe: %w", cfg.DisplayName, err)
    }
    var stderr bytes.Buffer
    cmd.Stderr = &stderr

    if err := cmd.Start(); err != nil {
        return "", fmt.Errorf("%s: start: %w", cfg.DisplayName, err)
    }

    maxLine := cfg.MaxLineBytes
    if maxLine == 0 {
        maxLine = 1 << 20 // 1 MiB
    }
    scanner := bufio.NewScanner(stdout)
    scanner.Buffer(make([]byte, 0, 4096), maxLine)

    state := &StreamState{StartedAt: time.Now()}
    var final *StreamResult

    for scanner.Scan() {
        line := scanner.Bytes()
        events, done, herr := handler(line, state)
        if herr != nil {
            _ = cmd.Wait()
            return "", fmt.Errorf("%s: handler: %w", cfg.DisplayName, herr)
        }
        for _, ev := range events {
            ev.ProviderLabel = cfg.ProviderLabel
            if progress != nil {
                progress(ev)
            }
        }
        if done != nil {
            final = done
            break
        }
    }
    if scanner.Err() != nil {
        _ = cmd.Wait()
        return "", fmt.Errorf("%s: scan: %w", cfg.DisplayName, scanner.Err())
    }

    _ = cmd.Wait()

    if final == nil {
        return "", fmt.Errorf("%s: stream exited without result", cfg.DisplayName)
    }
    if final.Err != nil {
        return "", final.Err
    }
    // Emit synthetic PhaseDone for consumers of the progress callback.
    if progress != nil {
        progress(GenerationProgress{
            Phase:         PhaseDone,
            ProviderLabel: cfg.ProviderLabel,
            OutputTokens:  final.OutputTokens,
            DurationMs:    final.DurationMs,
        })
    }
    return final.Text, nil
}
```

