waitErr := cmd.Wait()

// Branch table (design doc Layer 2):
//   1. final.Err set          → return final.Err (outranks ctx)
//   2. final.Text set         → synthetic PhaseDone + return text
//   3. ctx.DeadlineExceeded   → pass-through sentinel
//   4. ctx.Canceled           → pass-through sentinel
//   5. no final, Wait ok      → "stream exited without result"
//   6. no final, Wait err, FallbackDetect → Task 10 (heartbeat)
//   7. no final, Wait err     → "<DisplayName>: <stderr>"
switch {
case final != nil && final.Err != nil:
    return "", final.Err
case final != nil && final.Text != "":
    if progress != nil {
        progress(GenerationProgress{
            Phase:         PhaseDone,
            ProviderLabel: cfg.ProviderLabel,
            OutputTokens:  final.OutputTokens,
            DurationMs:    final.DurationMs,
        })
    }
    return final.Text, nil
case errors.Is(ctx.Err(), context.DeadlineExceeded):
    return "", context.DeadlineExceeded
case errors.Is(ctx.Err(), context.Canceled):
    return "", context.Canceled
case waitErr == nil:
    return "", fmt.Errorf("%s: stream exited without result", cfg.DisplayName)
default:
    msg := strings.TrimSpace(stderr.String())
    if msg == "" {
        return "", fmt.Errorf("%s: stream failed: %w", cfg.DisplayName, waitErr)
    }
    return "", fmt.Errorf("%s: %s: %w", cfg.DisplayName, msg, waitErr)
}
```

