```go
// StreamConfig describes a single invocation of RunStreamingCLI.
// Zero value is not useful — callers must populate at least Binary, Args,
// DisplayName, and ProviderLabel.
type StreamConfig struct {
    // Runner defaults to exec.CommandContext when nil; tests substitute a fake.
    Runner TextCommandRunner
    // Binary is the executable name; passed through exec.LookPath.
    Binary string
    // DisplayName is the vendor-facing label used in formatted error messages,
    // e.g. "Claude", "Codex". Distinct from ProviderLabel (progress UI).
    DisplayName string
    // ProviderLabel is stamped on every emitted GenerationProgress event
    // before the progress callback fires, e.g. "Anthropic", "OpenAI".
    ProviderLabel string
    // Args is the full argv after the binary name; must include whatever
    // streaming-mode flags the provider CLI requires.
    Args []string
    // Stdin is piped to the subprocess; typically the summarization prompt.
    Stdin string
    // LegacyFallback is invoked when FallbackDetect reports the CLI rejected
    // streaming flags. Typically wraps the agent's non-streaming GenerateText.
    LegacyFallback func(ctx context.Context) (string, error)
    // FallbackDetect returns true when the captured stderr indicates the CLI
    // doesn't understand the streaming flags passed via Args (e.g. older
    // binary). Defaults to a shared heuristic when nil.
    FallbackDetect func(stderr string) bool
    // MaxLineBytes sizes the bufio.Scanner buffer. Zero means 1 MiB default.
    MaxLineBytes int
}

// StreamState is per-invocation mutable scratch passed to each handler call.
// The runner zeroes StartedAt and sets it to the time of the first line; it
// never touches OutputTokensEstimate or Custom (handler owns both).
type StreamState struct {
    StartedAt            time.Time
    OutputTokensEstimate int
    Custom               map[string]any
}

// StreamResult is what a StreamLineHandler returns when it detects the
// provider's terminal event. Exactly one of Text (success) or Err (failure)
// must be non-zero; the other stays at its zero value.
type StreamResult struct {
    Text         string
    Err          error
    OutputTokens int
    DurationMs   int
}

// StreamLineHandler parses one NDJSON line emitted by a provider CLI's
// streaming output. Contract:
//   - events: zero or more GenerationProgress values to forward to the
//     progress callback. Runner stamps ProviderLabel before forwarding.
//   - done: non-nil when this line was the terminal event. Runner stops
//     scanning once a non-nil done is returned.
//   - err: non-nil only for fatal parsing conditions that should abort the
//     stream. Individual malformed lines must return (nil, nil, nil) — the
//     runner logs a warn count and keeps scanning.
//
// Handlers MUST NOT retain the line []byte past the call — the runner
// reuses the underlying scanner buffer.
type StreamLineHandler func(line []byte, state *StreamState) (
    events []GenerationProgress,
    done *StreamResult,
    err error,
)
```

