In `text_generator_cli.go`, add above `RunWithHeartbeat`:

```go
// defaultHeartbeatNoiseFilter drops lines that are obviously not useful to
// the user: empty, ANSI-only spinner redraws, version/deprecation banners,
// or TLS warnings. Returns (kept, true) if the line should be emitted,
// or ("", false) to drop it. Truncates long lines to 100 chars + "...".
func defaultHeartbeatNoiseFilter(line string) (string, bool) {
    trimmed := strings.TrimSpace(line)
    if trimmed == "" {
        return "", false
    }
    // Drop ANSI-only lines (≥95% escape sequences).
    ansiChars := 0
    for i := 0; i < len(trimmed); i++ {
        if trimmed[i] == 0x1b || trimmed[i] < 0x20 {
            ansiChars++
        }
    }
    if len(trimmed) > 0 && ansiChars*100/len(trimmed) >= 95 {
        return "", false
    }
    lower := strings.ToLower(trimmed)
    for _, pattern := range []string{"version ", "deprecation notice", "warning: tls"} {
        if strings.HasPrefix(lower, pattern) {
            return "", false
        }
    }
    if len(trimmed) > 200 {
        return trimmed[:100] + "...", true
    }
    return trimmed, true
}
```

