    if err != nil {
        return "", fmt.Errorf("%s: stderr pipe: %w", cfg.ProviderLabel, err)
    }

    start := time.Now()
    if err := cmd.Start(); err != nil {
        return "", fmt.Errorf("%s: start: %w", cfg.ProviderLabel, err)
    }

    // Stderr buffer is also captured for error reporting (up to 10 KB).
    // Scanner runs in the main goroutine — bufio.Scanner holds its own buffer.
    var stderrRaw bytes.Buffer
    scanner := bufio.NewScanner(io.TeeReader(stderrPipe, &stderrRaw))
    scanner.Buffer(make([]byte, 0, 4096), 1<<20)
    for scanner.Scan() {
        line := scanner.Text()
        kept, ok := defaultHeartbeatNoiseFilter(line)
        if !ok {
            continue
        }
        if cfg.StderrFilter != nil && !cfg.StderrFilter(kept) {
            continue
        }
        if progress != nil {
            progress(GenerationProgress{
                Phase:         PhaseMessage,
                ProviderLabel: cfg.ProviderLabel,
                Message:       kept,
            })
        }
        if stderrRaw.Len() >= 10*1024 {
            // Stop tee-buffering once we hit the 10 KB cap; scanner keeps
            // reading for progress but the error buffer stops growing.
            _, _ = io.Copy(io.Discard, stderrPipe)
            break
        }
    }

    waitErr := cmd.Wait()
    elapsed := time.Since(start)

    if waitErr != nil {
        msg := strings.TrimSpace(stderrRaw.String())
        if msg == "" {
            return "", fmt.Errorf("%s: heartbeat run: %w", cfg.ProviderLabel, waitErr)
        }
        return "", fmt.Errorf("%s: %s: %w", cfg.ProviderLabel, msg, waitErr)
    }

    if progress != nil {
        progress(GenerationProgress{
            Phase:         PhaseDone,
            ProviderLabel: cfg.ProviderLabel,
            DurationMs:    int(elapsed.Milliseconds()),
        })
    }

    return strings.TrimSpace(stdout.String()), nil
