// RunWithHeartbeat runs a blocking CLI invocation and emits synthetic
// progress events around it: PhaseConnecting at start, PhaseDone on
// success. Task 14 adds stderr tee as PhaseMessage events. Returns the
// raw stdout text, trimmed.
//
// When runner is nil, exec.CommandContext is used (production default).
// Tests inject a fake runner for deterministic subprocess behavior.
func RunWithHeartbeat(
    ctx context.Context,
    cfg HeartbeatConfig,
    binary string,
    args []string,
    stdin string,
    progress ProgressFn,
    runner TextCommandRunner,
) (string, error) {
    if runner == nil {
        runner = exec.CommandContext
    }

    if progress != nil {
        progress(GenerationProgress{
            Phase:         PhaseConnecting,
            ProviderLabel: cfg.ProviderLabel,
        })
    }

    cmd := runner(ctx, binary, args...)
    cmd.Dir = os.TempDir()
    cmd.Env = StripGitEnv(os.Environ())
    if stdin != "" {
        cmd.Stdin = strings.NewReader(stdin)
    }

    var stdout, stderr bytes.Buffer
    cmd.Stdout = &stdout
    cmd.Stderr = &stderr

    start := time.Now()
    if err := cmd.Run(); err != nil {
        return "", fmt.Errorf("%s: heartbeat run: %w", cfg.ProviderLabel, err)
    }
    elapsed := time.Since(start)

    if progress != nil {
        progress(GenerationProgress{
            Phase:         PhaseDone,
            ProviderLabel: cfg.ProviderLabel,
            DurationMs:    int(elapsed.Milliseconds()),
        })
    }

    return strings.TrimSpace(stdout.String()), nil
}
```

