```go
// ChooseGenerateTextPath dispatches to streaming, heartbeat, or silent
// GenerateText based on the agent's declared capabilities and whether
// the caller wants progress events.
//
// Rules:
//   - Agent implements StreamingTextGenerator AND progress != nil → streaming
//   - Agent implements TextGenerator AND progress != nil          → heartbeat
//   - Agent implements TextGenerator AND progress == nil          → silent
//   - Agent implements neither                                     → error
//
// Progress events are forwarded only in the first two branches.
func ChooseGenerateTextPath(
    ctx context.Context,
    ag agent.Agent,
    prompt, model string,
    progress agent.ProgressFn,
) (string, error) {
    if stg, ok := agent.AsStreamingTextGenerator(ag); ok && progress != nil {
        return stg.GenerateTextStreaming(ctx, prompt, model, progress)
    }
    tg, ok := agent.AsTextGenerator(ag)
    if !ok {
        return "", fmt.Errorf("agent %s does not support text generation", ag.Name())
    }
    if progress == nil {
        return tg.GenerateText(ctx, prompt, model) // condensation path
    }
    // Heartbeat path: wrap blocking GenerateText with synthetic progress.
    return agent.RunWithHeartbeat(ctx, agent.HeartbeatConfig{
        ProviderLabel: providerLabelFor(ag.Name()),
    }, binaryFor(ag.Name()), argsFor(ag.Name(), model), prompt, progress, nil)
}

// providerLabelFor maps an agent name to the user-facing provider label
// used in progress copy and error messages.
func providerLabelFor(name types.AgentName) string {
    switch name {
    case agent.AgentNameClaudeCode:
        return "Anthropic"
    case agent.AgentNameCodex:
        return "OpenAI"
    case agent.AgentNameCursor:
        return "Cursor"
    case agent.AgentNameGemini:
        return "Google"
    case agent.AgentNameCopilotCLI:
        return "GitHub"
    default:
        return string(name)
    }
}

// binaryFor returns the CLI binary name for heartbeat-mode subprocess
// invocation. Matches the binaries in text_generator_cli.go's summaryProviderBinaries.
func binaryFor(name types.AgentName) string {
    switch name {
    case agent.AgentNameClaudeCode:
        return "claude"
    case agent.AgentNameCodex:
        return "codex"
    case agent.AgentNameCursor:
        return "agent"
    case agent.AgentNameGemini:
        return "gemini"
    case agent.AgentNameCopilotCLI:
        return "copilot"
    default:
        return ""
    }
}

// argsFor returns the non-streaming argv for heartbeat-mode invocation,
// mirroring each agent's existing GenerateText implementation.
func argsFor(name types.AgentName, model string) []string {
    switch name {
    case agent.AgentNameClaudeCode:
        args := []string{"--print", "--output-format", "json", "--setting-sources", ""}
        if model != "" {
            args = append(args, "--model", model)
        }
        return args
    case agent.AgentNameCodex:
        args := []string{"exec", "--skip-git-repo-check"}
        if model != "" {
            args = append(args, "--model", model)
        }
        return append(args, "-")
    case agent.AgentNameCursor:
        args := []string{"--print", "--force", "--trust", "--workspace", os.TempDir()}
        if model != "" {
            args = append(args, "--model", model)
        }
        return args
    case agent.AgentNameGemini:
        args := []string{"-p", " "}
        if model != "" {
            args = append(args, "--model", model)
        }
        return args
    case agent.AgentNameCopilotCLI:
        args := []string{"--allow-all-tools", "--disable-builtin-mcps"}
        if model != "" {
            args = append(args, "--model", model)
        }
        return args
    default:
        return nil
    }
}
```

