func TestSummaryProgressWriter_PhaseMessageRendering(t *testing.T) {
    t.Parallel()
    var buf bytes.Buffer
    w := newSummaryProgressWriter(&buf)
    // Emit a Generating event first so lastLine is populated; then a Message
    // event. If PhaseMessage used updateLine (overwrite-in-place), it would
    // overwrite the Generating line and the buffer wouldn't contain BOTH.
    // Using printLine means both lines appear sequentially.
    w.handle(agent.GenerationProgress{Phase: agent.PhaseGenerating, ProviderLabel: "Gemini", OutputTokens: 42})
    w.handle(agent.GenerationProgress{
        Phase: agent.PhaseMessage, ProviderLabel: "Gemini",
        Message: "Loading MCP servers",
    })
    got := buf.String()
    if !strings.Contains(got, "Gemini: Loading MCP servers") {
        t.Errorf("expected 'Gemini: Loading MCP servers'; got %q", got)
    }
    // Both lines must coexist — Generating line is not overwritten by Message.
    if !strings.Contains(got, "Writing summary") {
        t.Errorf("Generating line was overwritten; PhaseMessage should printLine, not updateLine: %q", got)
    }
}

