// codexLooksLikeUnrecognizedFlag returns true when stderr indicates the CLI
// rejected the --json streaming flag (older codex binary, etc.).
func codexLooksLikeUnrecognizedFlag(stderr string) bool {
    lower := strings.ToLower(stderr)
    return (strings.Contains(lower, "unknown") || strings.Contains(lower, "unrecognized")) &&
        (strings.Contains(lower, "--json") || strings.Contains(lower, "-json"))
}
