var codexStreamHandler agent.StreamLineHandler = func(
    line []byte, state *agent.StreamState,
) ([]agent.GenerationProgress, *agent.StreamResult, error) {
    var ev codexStreamEvent
    if err := json.Unmarshal(line, &ev); err != nil {
        return nil, nil, nil
    }
    var events []agent.GenerationProgress

    switch ev.Type {
    case "<first-token-event-type>": // fill from Task 30
        events = append(events, agent.GenerationProgress{Phase: agent.PhaseFirstToken})
        if ev.Usage != nil {
            events[len(events)-1].InputTokens = ev.Usage.InputTokens
        }
    case "thread.message.delta", "<delta-event-type>":
        state.OutputTokensEstimate += len(ev.Delta) / 4
        events = append(events, agent.GenerationProgress{
            Phase:        agent.PhaseGenerating,
            OutputTokens: state.OutputTokensEstimate,
        })
    case "session.completed", "<terminal-event-type>":
        text := ""
        if ev.OutputText != nil {
            text = *ev.OutputText
        }
        outputTokens := 0
        if ev.Usage != nil {
            outputTokens = ev.Usage.OutputTokens
        }
        return events, &agent.StreamResult{
            Text: text, OutputTokens: outputTokens, DurationMs: ev.DurationMs,
        }, nil
    case "error":
        if ev.Error != nil {
            return events, &agent.StreamResult{
                Err: classifyCodexEnvelopeError(ev.Error),
            }, nil
        }
        return events, &agent.StreamResult{Err: &agent.Error{
            Kind: agent.ErrorUnknown, Provider: "OpenAI", Message: "codex reported unspecified error",
        }}, nil
    }
    return events, nil, nil
}
```

