- [ ] **Step 3: Add `classifyCodexEnvelopeError` helper**

```go
// classifyCodexEnvelopeError maps a Codex error envelope to *agent.Error.
// Relies on HTTP-status when provided; otherwise infers from error code.
func classifyCodexEnvelopeError(e *codexStreamErrorMsg) *agent.Error {
    kind := agent.ErrorUnknown
    switch {
    case e.Status == 401 || e.Status == 403:
        kind = agent.ErrorAuth
    case e.Status == 429:
        kind = agent.ErrorRateLimit
    case e.Status >= 400 && e.Status < 500:
        kind = agent.ErrorConfig
    case strings.Contains(strings.ToLower(e.Code), "auth"):
        kind = agent.ErrorAuth
    case strings.Contains(strings.ToLower(e.Code), "rate"):
        kind = agent.ErrorRateLimit
    }
    return &agent.Error{
        Kind: kind, Provider: "OpenAI", Message: e.Message, APIStatus: e.Status,
    }
}
```

